/** Month index -> [year, month] (1-based month). */
export function spxMonth(i: number): [number, number] {
  const t = (SPX_START_YEAR - 1) * 12 + (SPX_START_MONTH - 1) + i
  return [Math.floor(t / 12) + 1, (t % 12) + 1]
}

/** Index of the first observation in `year` (clamped to the series). */
export function spxIndexOfYear(year: number): number {
  const i = (year - SPX_START_YEAR) * 12 - (SPX_START_MONTH - 1)
  return Math.max(0, Math.min(SPX_NOMINAL.length - 1, i))
}
